SELECT DEPT_NM , D_BUYER_NM , CASE GUBUN WHEN 1 THEN '상품매출' WHEN 2 THEN '상품매출' WHEN 3 THEN '상품매출' WHEN 4 THEN '물류FEE' WHEN 5 THEN '물류FEE' WHEN 6 THEN '물류FEE' WHEN 7 THEN '계' WHEN 8 THEN '계' WHEN 9 THEN '계' WHEN 17 THEN '누계' WHEN 18 THEN '누계' WHEN 19 THEN '누계' END AS SALE_GUBUN , CASE GUBUN WHEN 1 THEN '매출' WHEN 2 THEN '매출이익' WHEN 3 THEN '매익율' WHEN 4 THEN '매출' WHEN 5 THEN '매출이익' WHEN 6 THEN '매익율' WHEN 7 THEN '매출' WHEN 8 THEN '매출이익' WHEN 9 THEN '매익율' WHEN 17 THEN '매출' WHEN 18 THEN '매출이익' WHEN 19 THEN '매익율' END AS TYPE_GUBUN , MAX(A_AMT) AS A_AMT , MAX(B_AMT) AS B_AMT , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT),0,0, ROUND(MAX(B_AMT)/MAX(A_AMT)*100,2)) END AS C_RATE , MAX(A_AMT01) AS A_AMT01 , MAX(B_AMT01) AS B_AMT01 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT01),0,0, ROUND(MAX(B_AMT01)/MAX(A_AMT01)*100,2)) END AS C_RATE01 , MAX(A_AMT02) AS A_AMT02 , MAX(B_AMT02) AS B_AMT02 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT02),0,0, ROUND(MAX(B_AMT02)/MAX(A_AMT02)*100,2)) END AS C_RATE02 , MAX(A_AMT03) AS A_AMT03 , MAX(B_AMT03) AS B_AMT03 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT03),0,0, ROUND(MAX(B_AMT03)/MAX(A_AMT03)*100,2)) END AS C_RATE03 , MAX(A_AMT04) AS A_AMT04 , MAX(B_AMT04) AS B_AMT04 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT04),0,0, ROUND(MAX(B_AMT04)/MAX(A_AMT04)*100,2)) END AS C_RATE04 , MAX(A_AMT05) AS A_AMT05 , MAX(B_AMT05) AS B_AMT05 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT05),0,0, ROUND(MAX(B_AMT05)/MAX(A_AMT05)*100,2)) END AS C_RATE05 , MAX(A_AMT06) AS A_AMT06 , MAX(B_AMT06) AS B_AMT06 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT06),0,0, ROUND(MAX(B_AMT06)/MAX(A_AMT06)*100,2)) END AS C_RATE06 , MAX(A_AMT07) AS A_AMT07 , MAX(B_AMT07) AS B_AMT07 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT07),0,0, ROUND(MAX(B_AMT07)/MAX(A_AMT07)*100,2)) END AS C_RATE07 , MAX(A_AMT08) AS A_AMT08 , MAX(B_AMT08) AS B_AMT08 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT08),0,0, ROUND(MAX(B_AMT08)/MAX(A_AMT08)*100,2)) END AS C_RATE08 , MAX(A_AMT09) AS A_AMT09 , MAX(B_AMT09) AS B_AMT09 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT09),0,0, ROUND(MAX(B_AMT09)/MAX(A_AMT09)*100,2)) END AS C_RATE09 , MAX(A_AMT10) AS A_AMT10 , MAX(B_AMT10) AS B_AMT10 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT10),0,0, ROUND(MAX(B_AMT10)/MAX(A_AMT10)*100,2)) END AS C_RATE10 , MAX(A_AMT11) AS A_AMT11 , MAX(B_AMT11) AS B_AMT11 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT11),0,0, ROUND(MAX(B_AMT11)/MAX(A_AMT11)*100,2)) END AS C_RATE11 , MAX(A_AMT12) AS A_AMT12 , MAX(B_AMT12) AS B_AMT12 , CASE WHEN GUBUN IN (3,6,9) THEN NULL ELSE DECODE(MAX(A_AMT12),0,0, ROUND(MAX(B_AMT12)/MAX(A_AMT12)*100,2)) END AS C_RATE12 , D_BUYER , DEPT_CD -- , DEPT_NM , P_DEPT_NM , LEVEL_NO FROM ( SELECT Y.D_BUYER_NM , Y.L_SEQ AS GUBUN , SUM(CASE WHEN SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT , SUM(CASE WHEN SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT01 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT01 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT02 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT02 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT03 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT03 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT04 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT04 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT05 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT05 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '06' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT06 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '06' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT06 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '07' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT07 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '07' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT07 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '08' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT08 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '08' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT08 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '09' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT09 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '09' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT09 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '10' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT10 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '10' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT10 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '11' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT11 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '11' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT11 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '12' AND SUBSTR(X.GUBUN,1,1) = 'A' THEN MT_AMT ELSE 0 END ) A_AMT12 , SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '12' AND SUBSTR(X.GUBUN,1,1) = 'B' THEN MT_AMT ELSE 0 END ) B_AMT12 , Y.D_BUYER , Y.DEPT_CD , Y.DEPT_NM , Y.P_DEPT_NM , 1 AS LEVEL_NO FROM KEP_MIS_SALES X,(SELECT A.DEPT_CD,A.D_BUYER, A.D_BUYER_NM,B.L_SEQ,B.GUBUN, A.DEPT_NM, P_DEPT_NM FROM (SELECT DEPT_CD,D_BUYER,D_BUYER_NM, DEPT_NM, P_DEPT_NM FROM KEP_MIS_CODE WHERE #{year} BETWEEN SUBSTR(F_DATE,1,4) AND SUBSTR(T_DATE,1,4) GROUP BY DEPT_CD, D_BUYER, D_BUYER_NM, DEPT_NM, P_DEPT_NM) A, (SELECT LEVEL AS L_SEQ , CASE LEVEL WHEN 1 THEN 'A' WHEN 2 THEN 'B' WHEN 3 THEN 'C' WHEN 4 THEN 'E' WHEN 5 THEN 'E' WHEN 6 THEN 'F' WHEN 7 THEN 'I' WHEN 8 THEN 'J' WHEN 9 THEN 'K' END AS GUBUN FROM DUAL CONNECT BY LEVEL <= 9 ) B) Y WHERE YYYYMM(+) BETWEEN #{year}||#{fromMonth} AND #{year}||#{toMonth}
AND Y.DEPT_CD = #{st_user_dept}
AND X.GUBUN(+) IN ('AA','AB','AE','BA','BB','BE','BF') AND SUBSTR(DECODE(X.GUBUN(+),'BF','BE',X.GUBUN(+)),2,1) = Y.GUBUN AND X.DEPT_CD(+) = Y.DEPT_CD AND X.D_BUYER(+) = Y.D_BUYER GROUP BY Y.D_BUYER_NM , Y.D_BUYER , Y.L_SEQ , Y.DEPT_CD , Y.DEPT_NM , Y.P_DEPT_NM UNION SELECT D_BUYER_NM , CASE GUBUN WHEN 'AA' THEN 3 WHEN 'AB' THEN 3 WHEN 'BA' THEN 3 WHEN 'BB' THEN 3 WHEN 'AE' THEN 6 WHEN 'BE' THEN 6 WHEN 'BF' THEN 6 END AS GUBUN , ROUND(DECODE(SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT , ROUND(DECODE(SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END )) * 100,2) AS B_AMT
, ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT01 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '01' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END )) * 100,2) AS B_AMT01 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT02 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '02' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END )) * 100,2) AS B_AMT02 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT03 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '03' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END )) * 100,2) AS B_AMT03 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT04 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '04' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END )) * 100,2) AS B_AMT04 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AB','AE') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'A' AND GUBUN IN ('AA','AE') THEN MT_AMT ELSE 0 END )) * 100,2) AS A_AMT05 , ROUND(DECODE(SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT ELSE 0 END),0,0, SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BB','BE','BF') THEN MT_AMT ELSE 0 END ) / SUM(CASE WHEN SUBSTR(YYYYMM,5,2) = '05' AND SUBSTR(GUBUN,1,1) = 'B' AND GUBUN IN ('BA','BE','BF') THEN MT_AMT